/* ---------------- STATE / DB ---------------- */
let state = null;
let dbRef = null;
let saving = false, pendingSave = false;
let activeTab = 'beranda';
let storageMode = 'local'; // 'db' when running inside a Claude artifact, else 'local'
const LOCAL_KEY = 'kelasMadinState_v1';

function loadFromLocalStorage(){
  try{
    const raw = localStorage.getItem(LOCAL_KEY);
    return raw ? JSON.parse(raw) : null;
  }catch(e){ console.error(e); return null; }
}
function saveToLocalStorage(){
  try{ localStorage.setItem(LOCAL_KEY, JSON.stringify(state)); }
  catch(e){ console.error(e); showToast('Gagal menyimpan ke penyimpanan lokal.'); }
}

async function initApp(){
  // Try Claude's artifact database first (only available when run inside a Claude artifact).
  try{
    if(typeof claude !== 'undefined' && claude.use){
      const db = await claude.use('db');
      if(db){
        storageMode = 'db';
        dbRef = db.doc('kelas/main');
        dbRef.onSnapshot((snap)=>{
          if(snap.exists && snap.data() && snap.data().students){
            state = snap.data();
          } else if(!state){
            state = defaultState();
            persist();
          }
          if(migrateGenders()) persist();
          render();
          maybeShowFirstRunQuranPrompt();
        }, ()=>{ if(!state){ state = defaultState(); render(); } });
        return;
      }
    }
  }catch(e){ /* fall through to localStorage */ }

  // Standalone / GitHub Pages mode: persist with localStorage.
  storageMode = 'local';
  state = loadFromLocalStorage() || defaultState();
  if(migrateGenders()) saveToLocalStorage();
  render();
  maybeShowFirstRunQuranPrompt();
}

async function persist(){
  if(storageMode==='db'){
    if(!dbRef) return;
    if(saving){ pendingSave = true; return; }
    saving = true;
    try{ await dbRef.set(state); }
    catch(e){
      console.error(e);
      showToast('Gagal menyimpan perubahan. Coba lagi.');
    }
    saving = false;
    if(pendingSave){ pendingSave = false; persist(); }
    return;
  }
  saveToLocalStorage();
}

function saveAndRender(){ persist(); render(); }


/* ---------------- POINTS ENGINE ---------------- */
function applyDeltas(deltas, note, type){
  // deltas: [{studentId, delta}]
  const touched = [];
  let totalPositive = 0;
  deltas.forEach(d=>{
    if(!d.delta) return;
    const s = state.students.find(x=>x.id===d.studentId);
    if(!s) return;
    s.points = clamp((s.points||0) + d.delta, 0, 999999);
    state.logs.unshift({ id:uid(), studentId:d.studentId, type, delta:d.delta, note:note||'', date:todayKey(), ts:Date.now() });
    if(d.delta > 0) totalPositive += d.delta;
    touched.push({id:d.studentId, delta:d.delta, name:s.name});
  });
  if(state.logs.length > 400) state.logs = state.logs.slice(0,400);
  saveAndRender();
  return { touched, totalPositive };
}

function kelasTotalPoin(){ return (state.students||[]).reduce((a,s)=>a+(s.points||0),0); }

/* ---------------- CELEBRATION / TOAST ---------------- */
function showCelebration(points, msg, touched){
  const root = document.getElementById('celebRoot');
  root.innerHTML = '';
  if(points <= 0){ showToast(msg); return; }
  const colors = ['#E8B93E','#7FA085','#D98AA1','#7FA6C9','#9C8ED9'];
  let confetti = '';
  for(let i=0;i<26;i++){
    const left = Math.random()*100;
    const delay = Math.random()*0.4;
    const dur = 1.6 + Math.random()*0.9;
    const color = colors[i%colors.length];
    confetti += `<div class="confetti" style="left:${left}%;background:${color};animation-duration:${dur}s;animation-delay:${delay}s;"></div>`;
  }
  root.innerHTML = `
    <div class="celeb-overlay">
      ${confetti}
      <div class="celeb-card">
        <span class="celeb-star">⭐</span>
        <div class="celeb-pts">+${points} Poin</div>
        <div class="celeb-msg">${msg}</div>
      </div>
    </div>`;
  setTimeout(()=>{ root.innerHTML=''; }, 1900);

  setTimeout(()=>{
    (touched||[]).forEach(t=>{
      if(t.delta<=0) return;
      const card = document.querySelector(`.student-card[data-id="${t.id}"]`);
      if(card){
        card.classList.add('card-flash');
        const fp = document.createElement('div');
        fp.className='float-plus';
        fp.textContent = '+'+t.delta;
        card.appendChild(fp);
        setTimeout(()=>{ fp.remove(); card.classList.remove('card-flash'); }, 1300);
      }
    });
  }, 60);
}

function showToast(msg){
  const root = document.getElementById('toastRoot');
  const el = document.createElement('div');
  el.className='toast';
  el.textContent = msg;
  root.appendChild(el);
  setTimeout(()=>el.remove(), 2200);
}

/* ---------------- MODAL HELPERS ---------------- */
function openModal(title, bodyHtml, footHtml){
  const root = document.getElementById('modalRoot');
  root.innerHTML = `
    <div class="modal-overlay" id="modalOverlay">
      <div class="modal-sheet">
        <div class="modal-head"><h3>${title}</h3><button class="close-x" id="modalCloseBtn">✕</button></div>
        <div class="modal-body">${bodyHtml}</div>
        ${footHtml ? `<div class="modal-foot">${footHtml}</div>` : ''}
      </div>
    </div>`;
  document.getElementById('modalCloseBtn').onclick = closeModal;
  document.getElementById('modalOverlay').addEventListener('click', (e)=>{ if(e.target.id==='modalOverlay') closeModal(); });
}
function closeModal(){ document.getElementById('modalRoot').innerHTML=''; }

/* ---------------- RENDER: MAIN ---------------- */
function render(){
  if(!state) return;
  document.getElementById('kelasPoinNum').textContent = kelasTotalPoin();
  applyTampilanSettings();
  document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active', b.dataset.tab===activeTab));
  const screen = document.getElementById('screen');
  if(activeTab==='beranda') screen.innerHTML = renderBeranda();
  else if(activeTab==='materi') screen.innerHTML = renderMateri();
  else if(activeTab==='peringkat') screen.innerHTML = renderPeringkat();
  else if(activeTab==='profil') screen.innerHTML = renderProfil();
  else if(activeTab==='pengaturan') screen.innerHTML = renderPengaturan();
  else screen.innerHTML = renderProfil();
  bindScreenEvents();
}

function applyTampilanSettings(){
  const set = state.settings || {};
  const h1 = document.querySelector('.brand-text h1');
  const p = document.querySelector('.brand-text p');
  const greet = document.getElementById('greetSub');
  if(h1) h1.textContent = set.appName || 'Kelas Madin';
  if(p) p.textContent = set.tagline || 'Belajar • Beramal • Jadi Anak Sholeh';
  if(greet) greet.textContent = set.greeting || 'semangat belajar hari ini! ✨';
  document.title = set.appName || 'Kelas Madin';
}

function bindScreenEvents(){
  document.querySelectorAll('[data-action]').forEach(el=>{
    el.onclick = ()=> openActionModal(el.dataset.action);
  });
  document.querySelectorAll('[data-open-student]').forEach(el=>{
    el.onclick = ()=> openStudentDetail(el.dataset.openStudent);
  });
  const notif = document.getElementById('notifBanner');
  if(notif) notif.onclick = openTodayLog;
  const jurnalNoteBanner = document.getElementById('jurnalNoteBanner');
  if(jurnalNoteBanner) jurnalNoteBanner.onclick = openJurnalModal;
  const addSiswaBtn = document.getElementById('addSiswaBtn');
  if(addSiswaBtn) addSiswaBtn.onclick = openAddStudent;
  const addMateriBtn = document.getElementById('addMateriBtn');
  if(addMateriBtn) addMateriBtn.onclick = openAddMateri;
  document.querySelectorAll('[data-materi-toggle]').forEach(el=>{
    el.onclick = ()=> toggleMateriDone(el.dataset.materiToggle);
  });
  document.querySelectorAll('[data-edit-siswa]').forEach(el=>{
    el.onclick = (e)=>{ e.stopPropagation(); openEditStudent(el.dataset.editSiswa); };
  });
  document.querySelectorAll('[data-del-siswa]').forEach(el=>{
    el.onclick = (e)=>{ e.stopPropagation(); deleteStudent(el.dataset.delSiswa); };
  });
  const dlAllJuzBtn = document.getElementById('dlAllJuzBtn');
  if(dlAllJuzBtn) dlAllJuzBtn.onclick = openDownloadAllJuzModal;
  const openRekapBtn = document.getElementById('openRekapBtn');
  if(openRekapBtn) openRekapBtn.onclick = openRekapModal;
  const openRekapBtn2 = document.getElementById('openRekapBtn2');
  if(openRekapBtn2) openRekapBtn2.onclick = openRekapModal;
  const openQuranRekapBtn = document.getElementById('openQuranRekapBtn');
  if(openQuranRekapBtn) openQuranRekapBtn.onclick = openQuranRekapModal;
  const pengBackBtn = document.getElementById('pengBackBtn');
  if(pengBackBtn) pengBackBtn.onclick = ()=>{ activeTab='beranda'; render(); };
  const editTampilanBtn = document.getElementById('editTampilanBtn');
  if(editTampilanBtn) editTampilanBtn.onclick = openTampilanModal;
  const editJadwalBtn = document.getElementById('editJadwalBtn');
  if(editJadwalBtn) editJadwalBtn.onclick = openJadwalModal;
  const editMapelBtn = document.getElementById('editMapelBtn');
  if(editMapelBtn) editMapelBtn.onclick = openMapelModal;
  const editAturanPoinBtn = document.getElementById('editAturanPoinBtn');
  if(editAturanPoinBtn) editAturanPoinBtn.onclick = openAturanPoinModal;
  const goMateriBtn = document.getElementById('goMateriBtn');
  if(goMateriBtn) goMateriBtn.onclick = ()=>{ activeTab='materi'; render(); };
  const resetBtn = document.getElementById('resetDataBtn');
  if(resetBtn) resetBtn.onclick = ()=>{
    if(confirm('Reset semua data kelas? Tindakan ini tidak bisa dibatalkan.')){
      state = defaultState();
      saveAndRender();
    }
  };
}

/* ---------------- BERANDA ---------------- */
function renderBeranda(){
  const students = state.students||[];
  const todayLogs = state.logs.filter(l=>l.date===todayKey() && l.delta>0);
  const todayStudentIds = [...new Set(todayLogs.map(l=>l.studentId))];
  const lastJurnal = [...(state.jurnal||[])].sort((a,b)=> b.date.localeCompare(a.date))[0];
  const showJurnalReminder = lastJurnal && lastJurnal.catatan && lastJurnal.date !== todayKey();

  const quick = Object.entries(ACTIONS).map(([key,a])=>`
    <button class="quick-btn" data-action="${key}">
      <div class="quick-icon" style="background:${a.bg}">${a.icon}</div>
      <span class="label">${a.label}</span>
    </button>`).join('');

  const maxPts = students.length ? Math.max(...students.map(s=>s.points||0)) : 0;
  const cards = students.map((s,i)=>{
    const st = avatarStyle(s.avatarIdx ?? i);
    const isTop = maxPts>0 && (s.points||0)===maxPts;
    return `
    <div class="student-card ${isTop?'top-scorer':''}" data-id="${s.id}" data-open-student="${s.id}">
      <div class="avatar-wrap">
        ${isTop?'<span class="crown">👑</span><span class="spark spark-a">✨</span><span class="spark spark-b">⭐</span>':''}
        <div class="avatar-ring" style="background:${st.bg}">${avatarOf(s)}</div>
        <div class="pt-badge">⭐${s.points}</div>
      </div>
      <div class="student-name">${s.name.split(' ')[0]}</div>
      ${isTop?'<div class="top-tag">Juara Poin!</div>':''}
    </div>`;
  }).join('');

  return `
    <div class="beranda-scene">
      <div class="section-title on-scene">Siswa <span class="sub">${students.length} anak</span></div>
      <div class="student-grid">${cards || '<div class="empty-note">Belum ada siswa. Tambahkan di tab Profil.</div>'}</div>

      <div class="notif-banner" id="notifBanner">
        <span class="ic">📣</span>
        <div class="txt">Hari ini ada <b>${todayStudentIds.length} siswa</b> yang mendapat poin!</div>
        <span class="chev">›</span>
      </div>
      ${showJurnalReminder ? `
      <div class="notif-banner" id="jurnalNoteBanner">
        <span class="ic">📌</span>
        <div class="txt">Catatan pertemuan lalu: <b>${lastJurnal.catatan.replace(/&/g,'&amp;').replace(/</g,'&lt;')}</b></div>
        <span class="chev">›</span>
      </div>` : ''}
    </div>

    <div class="section-title">Aksi Cepat</div>
    <div class="quick-grid">${quick}</div>
  `;
}

function openTodayLog(){
  const todayLogs = state.logs.filter(l=>l.date===todayKey());
  const rows = todayLogs.map(l=>{
    const s = state.students.find(x=>x.id===l.studentId);
    const a = LOG_META[l.type] || {icon:'⭐',label:'Poin'};
    return `<div class="form-row">
      <div class="av-sm" style="background:var(--sage-soft)">${s?avatarOf(s):'?'}</div>
      <div class="fname">${s?s.name.split(' ')[0]:'—'}<div class="mini-note">${a.icon} ${a.label}${l.note?' · '+l.note:''}</div></div>
      <div style="font-weight:800;color:${l.delta>=0?'var(--gold-deep)':'var(--danger)'};font-size:13px;">${l.delta>=0?'+':''}${l.delta}</div>
    </div>`;
  }).join('') || '<div class="empty-note">Belum ada aktivitas hari ini.</div>';
  openModal('Aktivitas Hari Ini', rows, null);
}

/* ---------------- MATERI TAB ---------------- */
function renderMateri(){
  const items = state.materi||[];
  const rows = items.map((m,i)=>`
    <div class="materi-item">
      <div class="materi-ic">${MATERI_ICONS[i % MATERI_ICONS.length]}</div>
      <div class="materi-info"><b>${m.title}</b><span>${m.category}</span></div>
      <button class="materi-done-btn ${m.done?'done':''}" data-materi-toggle="${m.id}">${m.done?'✓ Selesai':'Tandai Selesai'}</button>
    </div>`).join('');
  return `
    <div class="section-title">Materi Pembelajaran <span class="sub">${items.length} materi</span></div>
    ${rows}
    <button class="add-materi-btn" id="addMateriBtn">+ Tambah Materi</button>
  `;
}

function toggleMateriDone(id){
  const m = state.materi.find(x=>x.id===id);
  if(!m) return;
  const willBeDone = !m.done;
  m.done = willBeDone;
  if(willBeDone){
    const deltas = state.students.map(s=>({studentId:s.id, delta:5}));
    const {touched,totalPositive} = applyDeltas(deltas, m.title, 'materi');
    showCelebration(totalPositive, `Materi "${m.title}" selesai! Semua siswa +5 poin.`, touched);
  } else {
    saveAndRender();
  }
}

function openAddMateri(){
  openModal('Tambah Materi', `
    <div class="field-label">Judul Materi</div>
    <input class="text-input" id="mTitle" placeholder="Contoh: Hafalan Surat An-Nas" />
    <div class="field-label">Kategori</div>
    <input class="text-input" id="mCat" placeholder="Contoh: Tahfidz" />
  `, `<button class="save-btn" id="mSaveBtn">Simpan Materi</button>`);
  document.getElementById('mSaveBtn').onclick = ()=>{
    const title = document.getElementById('mTitle').value.trim();
    const cat = document.getElementById('mCat').value.trim() || 'Umum';
    if(!title) return;
    state.materi.push({id:uid(), title, category:cat, done:false});
    saveAndRender();
    closeModal();
  };
}

/* ---------------- PERINGKAT TAB ---------------- */
function renderPeringkat(){
  const sorted = [...(state.students||[])].sort((a,b)=>b.points-a.points);
  const medals = ['🥇','🥈','🥉'];
  const rows = sorted.map((s,i)=>{
    const st = avatarStyle(s.avatarIdx ?? i);
    return `
    <div class="rank-row ${i<3?'top'+(i+1):''}">
      <div class="rank-num">${i<3?medals[i]:i+1}</div>
      <div class="rank-av" style="background:${st.bg}">${avatarOf(s)}</div>
      <div class="rank-name">${s.name}</div>
      <div class="rank-pt">${s.points} pt</div>
    </div>`;
  }).join('');
  return `
    <div class="section-title">Peringkat Kelas <span class="sub">Total ${kelasTotalPoin()} poin</span></div>
    <button class="outline-btn" id="openRekapBtn" style="margin-bottom:12px;">📈 Rekap Perkembangan (Mingguan/Bulanan/Semester)</button>
    ${rows || '<div class="empty-note">Belum ada siswa.</div>'}
  `;
}

/* ---------------- PROFIL TAB ---------------- */
function renderProfil(){
  const students = state.students||[];
  const rows = students.map((s,i)=>{
    const st = avatarStyle(s.avatarIdx ?? i);
    return `
    <div class="siswa-row" data-open-student="${s.id}">
      <div class="rank-av" style="background:${st.bg}">${avatarOf(s)}</div>
      <div class="meta"><b>${s.name}</b><span>${s.points} poin</span></div>
      <button class="icon-btn" data-edit-siswa="${s.id}">✎</button>
      <button class="icon-btn danger" data-del-siswa="${s.id}">🗑</button>
    </div>`;
  }).join('');
  return `
    <div class="profile-stats">
      <div class="stat-card"><div class="n">${students.length}</div><div class="l">Total Siswa</div></div>
      <div class="stat-card"><div class="n">${kelasTotalPoin()}</div><div class="l">Total Poin Kelas</div></div>
    </div>
    <div class="section-title">Data Siswa</div>
    ${rows}
    <button class="add-siswa-btn" id="addSiswaBtn">+ Tambah Siswa</button>
  `;
}

