function openTampilanModal(){
  const set = state.settings || {};
  openModal('Nama Aplikasi & Sambutan', `
    <div class="field-label">Nama Aplikasi</div>
    <input class="text-input" id="setAppName" placeholder="Kelas Madin" value="${(set.appName||'').replace(/"/g,'&quot;')}" />
    <div class="field-label">Slogan/Tagline</div>
    <input class="text-input" id="setTagline" placeholder="Belajar • Beramal • Jadi Anak Sholeh" value="${(set.tagline||'').replace(/"/g,'&quot;')}" />
    <div class="field-label">Pesan Sambutan</div>
    <input class="text-input" id="setGreeting" placeholder="semangat belajar hari ini! ✨" value="${(set.greeting||'').replace(/"/g,'&quot;')}" />
  `, `<button class="save-btn" id="setTampilanSave">Simpan</button>`);
  document.getElementById('setTampilanSave').onclick = ()=>{
    state.settings = state.settings || {};
    state.settings.appName = document.getElementById('setAppName').value.trim() || 'Kelas Madin';
    state.settings.tagline = document.getElementById('setTagline').value.trim() || 'Belajar • Beramal • Jadi Anak Sholeh';
    state.settings.greeting = document.getElementById('setGreeting').value.trim() || 'semangat belajar hari ini! ✨';
    saveAndRender();
    closeModal();
    showToast('Tampilan diperbarui');
  };
}

function openMapelModal(){
  function rows(){
    return (state.mataPelajaran||[]).map((m,i)=>`
      <div class="siswa-row">
        <div class="meta"><b>${m}</b></div>
        <button class="icon-btn danger" data-del-mapel="${i}">🗑</button>
      </div>`).join('') || '<div class="empty-note">Belum ada mata pelajaran.</div>';
  }
  function draw(){
    openModal('Kelola Mata Pelajaran', `
      <div id="mapelRows">${rows()}</div>
      <div class="field-label">Tambah Mata Pelajaran</div>
      <input class="text-input" id="mapelNew" placeholder="Contoh: Bahasa Arab" />
    `, `<button class="save-btn" id="mapelAddBtn">+ Tambah</button>`);
    document.querySelectorAll('[data-del-mapel]').forEach(btn=>{
      btn.onclick = ()=>{
        state.mataPelajaran.splice(parseInt(btn.dataset.delMapel,10),1);
        saveAndRender();
        draw();
      };
    });
    document.getElementById('mapelAddBtn').onclick = ()=>{
      const val = document.getElementById('mapelNew').value.trim();
      if(!val) return;
      state.mataPelajaran = state.mataPelajaran || [];
      if(!state.mataPelajaran.includes(val)) state.mataPelajaran.push(val);
      saveAndRender();
      draw();
    };
  }
  draw();
}

function openAturanPoinModal(){
  function rows(){
    return (state.aturanPoin||[]).map((r,i)=>`
      <div class="siswa-row">
        <div class="meta"><b>${r.label}</b><span>${r.poin>0?'+':''}${r.poin} poin</span></div>
        <button class="icon-btn danger" data-del-aturan="${i}">🗑</button>
      </div>`).join('') || '<div class="empty-note">Belum ada aturan poin.</div>';
  }
  function draw(){
    openModal('Aturan Poin', `
      <div id="aturanRows">${rows()}</div>
      <div class="field-label">Nama Aturan</div>
      <input class="text-input" id="aturanLabel" placeholder="Contoh: Hafalan Lancar" />
      <div class="field-label">Nilai Poin (isi minus untuk pengurangan, mis. -3)</div>
      <input class="text-input" id="aturanNilai" type="number" placeholder="Contoh: 5 atau -3" />
    `, `<button class="save-btn" id="aturanAddBtn">+ Tambah Aturan</button>`);
    document.querySelectorAll('[data-del-aturan]').forEach(btn=>{
      btn.onclick = ()=>{
        state.aturanPoin.splice(parseInt(btn.dataset.delAturan,10),1);
        saveAndRender();
        draw();
      };
    });
    document.getElementById('aturanAddBtn').onclick = ()=>{
      const label = document.getElementById('aturanLabel').value.trim();
      const nilai = parseInt(document.getElementById('aturanNilai').value,10);
      if(!label || isNaN(nilai) || nilai===0) return;
      state.aturanPoin = state.aturanPoin || [];
      state.aturanPoin.push({id:uid(), label, poin:nilai});
      saveAndRender();
      draw();
    };
  }
  draw();
}

function openJadwalModal(){
  let selectedDay = HARI_LIST[0];
  function itemsHtml(){
    const list = state.jadwalPelajaran[selectedDay] || [];
    return list.map((it,i)=>`
      <div class="siswa-row">
        <div class="meta"><b>${it.mapel}</b><span>${it.jam||''}</span></div>
        <button class="icon-btn danger" data-del-jadwal="${i}">🗑</button>
      </div>`).join('') || '<div class="empty-note">Belum ada jadwal untuk hari ini.</div>';
  }
  function mapelOptions(){
    const list = state.mataPelajaran||[];
    if(list.length===0) return '<option value="">(Belum ada mata pelajaran)</option>';
    return list.map(m=>`<option value="${m.replace(/"/g,'&quot;')}">${m}</option>`).join('');
  }
  function draw(){
    openModal('Atur Jadwal Pelajaran', `
      <div class="tab-toggle" style="flex-wrap:wrap;">
        ${HARI_LIST.map(h=>`<button class="${h===selectedDay?'active':''}" data-jday="${h}">${h}</button>`).join('')}
      </div>
      <div id="jadwalRows" style="margin-top:12px;">${itemsHtml()}</div>
      <div class="field-label">Mata Pelajaran</div>
      <select class="text-input" id="jMapel">${mapelOptions()}</select>
      <div class="field-label">Jam (opsional)</div>
      <input class="text-input" id="jJam" placeholder="Contoh: 14.00 - 15.00" />
    `, `<button class="save-btn" id="jAddBtn">+ Tambah ke ${selectedDay}</button>`);
    document.querySelectorAll('[data-jday]').forEach(btn=>{
      btn.onclick = ()=>{ selectedDay = btn.dataset.jday; draw(); };
    });
    document.querySelectorAll('[data-del-jadwal]').forEach(btn=>{
      btn.onclick = ()=>{
        state.jadwalPelajaran[selectedDay].splice(parseInt(btn.dataset.delJadwal,10),1);
        saveAndRender();
        draw();
      };
    });
    document.getElementById('jAddBtn').onclick = ()=>{
      const mapel = document.getElementById('jMapel').value;
      if(!mapel) return;
      const jam = document.getElementById('jJam').value.trim();
      state.jadwalPelajaran[selectedDay] = state.jadwalPelajaran[selectedDay] || [];
      state.jadwalPelajaran[selectedDay].push({id:uid(), mapel, jam});
      saveAndRender();
      draw();
    };
  }
  draw();
}

function genderSegHtml(current){
  return `<div class="field-label">Jenis Kelamin</div>
    <div class="seg" style="margin-bottom:14px;">
      <button type="button" data-gender-btn="L" class="${current==='P'?'':'on'}">👦 Laki-laki</button>
      <button type="button" data-gender-btn="P" class="${current==='P'?'on':''}">👧 Perempuan</button>
    </div>`;
}
function bindGenderSeg(getSet){
  document.querySelectorAll('[data-gender-btn]').forEach(btn=>{
    btn.onclick = ()=>{
      getSet(btn.dataset.genderBtn);
      document.querySelectorAll('[data-gender-btn]').forEach(b=>b.classList.toggle('on', b.dataset.genderBtn===btn.dataset.genderBtn));
    };
  });
}

function avatarPickerHtml(selectedIdx, gender){
  const lib = avatarLibFor(gender);
  const items = lib.map((src,i)=>`
    <button type="button" class="avatar-pick-item ${selectedIdx===i?'selected':''}" data-pick-idx="${i}">
      <img src="${src}" alt="">
    </button>`).join('');
  return `<div class="field-label">Pilih Avatar</div>
    <div class="avatar-picker-grid" id="avatarPickerGrid">
      <button type="button" class="avatar-pick-item none-item ${selectedIdx===-1?'selected':''}" data-pick-idx="-1">Pakai Ilustrasi</button>
      ${items}
    </div>`;
}
function bindAvatarPicker(getSet){
  document.querySelectorAll('[data-pick-idx]').forEach(btn=>{
    btn.onclick = ()=>{
      getSet(parseInt(btn.dataset.pickIdx,10));
      document.querySelectorAll('[data-pick-idx]').forEach(b=>b.classList.toggle('selected', b.dataset.pickIdx===btn.dataset.pickIdx));
    };
  });
}
function findLibraryIdx(s){
  if(!s) return -1;
  return typeof s.avatarLib === 'number' ? s.avatarLib : -1;
}

function openAddStudent(){
  let gender = 'L';
  let avIdx = -1;
  openModal('Tambah Siswa', `
    <div class="field-label">Nama Lengkap</div>
    <input class="text-input" id="sName" placeholder="Contoh: Zaid Abdullah" />
    ${genderSegHtml(gender)}
    <div id="avatarPickerWrap">${avatarPickerHtml(avIdx, gender)}</div>
  `, `<button class="save-btn" id="sSaveBtn">Simpan Siswa</button>`);
  bindAvatarPicker((v)=>{ avIdx = v; });
  bindGenderSeg((v)=>{
    gender = v; avIdx = -1;
    document.getElementById('avatarPickerWrap').innerHTML = avatarPickerHtml(avIdx, gender);
    bindAvatarPicker((v2)=>{ avIdx = v2; });
  });
  document.getElementById('sSaveBtn').onclick = ()=>{
    const name = document.getElementById('sName').value.trim();
    if(!name) return;
    const student = {id:uid(), name, avatarIdx: state.students.length, gender, points:0};
    if(avIdx>=0) student.avatarLib = avIdx;
    state.students.push(student);
    saveAndRender();
    closeModal();
  };
}

function openEditStudent(id){
  const s = state.students.find(x=>x.id===id);
  if(!s) return;
  let gender = s.gender==='P' ? 'P' : 'L';
  let avIdx = findLibraryIdx(s);
  openModal('Edit Siswa', `
    <div class="field-label">Nama Lengkap</div>
    <input class="text-input" id="sName" value="${s.name.replace(/"/g,'&quot;')}" />
    ${genderSegHtml(gender)}
    <div id="avatarPickerWrap">${avatarPickerHtml(avIdx, gender)}</div>
  `, `<button class="save-btn" id="sSaveBtn">Simpan Perubahan</button>`);
  bindAvatarPicker((v)=>{ avIdx = v; });
  bindGenderSeg((v)=>{
    gender = v; avIdx = -1;
    document.getElementById('avatarPickerWrap').innerHTML = avatarPickerHtml(avIdx, gender);
    bindAvatarPicker((v2)=>{ avIdx = v2; });
  });
  document.getElementById('sSaveBtn').onclick = ()=>{
    const name = document.getElementById('sName').value.trim();
    if(!name) return;
    s.name = name;
    s.gender = gender;
    delete s.photo;
    if(avIdx>=0){ s.avatarLib = avIdx; delete s.avatarKey; }
    else{ delete s.avatarLib; delete s.avatarKey; }
    saveAndRender();
    closeModal();
  };
}

function deleteStudent(id){
  const s = state.students.find(x=>x.id===id);
  if(!s) return;
  if(!confirm(`Hapus ${s.name} dari kelas?`)) return;
  state.students = state.students.filter(x=>x.id!==id);
  saveAndRender();
}

function openStudentDetail(id){
  const s = state.students.find(x=>x.id===id);
  if(!s) return;
  const st = avatarStyle(s.avatarIdx ?? 0);
  const logs = state.logs.filter(l=>l.studentId===id).slice(0,20);
  const logRows = logs.map(l=>{
    const a = LOG_META[l.type] || {icon:'⭐', label:'Poin'};
    return `<div class="form-row">
      <div class="av-sm" style="background:var(--sage-soft);color:var(--accent)">${a.icon}</div>
      <div class="fname">${a.label}${l.note?' · '+l.note:''}<div class="mini-note">${l.date}</div></div>
      <div style="font-weight:800;color:${l.delta>=0?'var(--gold-deep)':'var(--danger)'};font-size:13px;">${l.delta>=0?'+':''}${l.delta}</div>
    </div>`;
  }).join('') || '<div class="empty-note">Belum ada riwayat.</div>';

  const raportRows = (state.raport||[]).filter(r=>r.studentId===id).sort((a,b)=>a.mapel.localeCompare(b.mapel));
  const raportHtml = raportRows.length ? `
    <div class="field-label">Nilai Raport</div>
    ${raportRows.map(r=>`
      <div class="raport-row">
        <div class="fname" style="flex:1;">${r.mapel}</div>
        <div class="raport-mini">H:${r.avgHarian ?? '—'}</div>
        <div class="raport-mini">U:${r.avgUjian ?? '—'}</div>
        <div class="raport-final">${r.nilai}</div>
      </div>`).join('')}
  ` : '';

  openModal(s.name, `
    <div style="text-align:center;margin-bottom:14px;">
      <div class="avatar-ring" style="background:${st.bg};margin:0 auto 8px;width:70px;height:70px;">${avatarOf(s)}</div>
      <div class="pt-pill" style="font-size:14px;padding:5px 14px;">⭐ ${s.points} Poin</div>
    </div>
    ${raportHtml}
    <div class="field-label">Riwayat Aktivitas</div>
    ${logRows}
  `, `
    <div class="qty-ctrl" style="justify-content:center;gap:14px;">
      <button class="qty-btn" id="detMinus" style="width:36px;height:36px;font-size:16px;">−5</button>
      <span style="font-weight:800;font-size:12px;color:var(--ink-soft);">Poin Cepat</span>
      <button class="qty-btn" id="detPlus" style="width:36px;height:36px;font-size:16px;">+5</button>
    </div>
  `);
  document.getElementById('detPlus').onclick = ()=>{
    const {touched,totalPositive} = applyDeltas([{studentId:id, delta:5}], 'Tambahan cepat', 'poin');
    closeModal();
    showCelebration(totalPositive, `${s.name.split(' ')[0]} mendapat tambahan poin!`, touched);
  };
  document.getElementById('detMinus').onclick = ()=>{
    applyDeltas([{studentId:id, delta:-5}], 'Pengurangan cepat', 'poin');
    closeModal();
    showToast(`${s.name.split(' ')[0]} -5 poin`);
  };
}

/* ---------------- ACTION MODALS ---------------- */
function studentRowsTemplate(renderRight){
  return (state.students||[]).map((s,i)=>{
    const st = avatarStyle(s.avatarIdx ?? i);
    return `<div class="form-row" data-row-id="${s.id}">
      <div class="av-sm" style="background:${st.bg}">${avatarOf(s)}</div>
      <div class="fname">${s.name.split(' ')[0]}</div>
      ${renderRight(s)}
    </div>`;
  }).join('');
}

function openActionModal(key){
  if(key==='absensi') return openAbsensiModal();
  if(key==='nilai') return openNilaiModal();
  if(key==='raport') return openRaportModal();
  if(key==='piket') return openPiketModal();
  if(key==='quran') return openQuranModal();
  if(key==='jurnal') return openJurnalModal();
  if(key==='poin') return openPoinModal();
}

/* --- ABSENSI --- */
function openAbsensiModal(){
  const today = todayKey();
  const savedToday = state.absensi[today] || {};
  const isEdit = Object.keys(savedToday).length > 0;
  const statuses = {};
  (state.students||[]).forEach(s=> statuses[s.id] = savedToday[s.id] || 'Hadir');
  const STATUS_ORDER = ['Hadir','Sakit','Izin','Alpa'];
  const STATUS_PTS = {Hadir:5, Sakit:0, Izin:0, Alpa:-2};
  const STATUS_META = {
    Hadir:{icon:'✅', label:'Hadir', chip:'var(--sage-soft)'},
    Sakit:{icon:'🤒', label:'Sakit', chip:'var(--peach-soft)'},
    Izin:{icon:'📩', label:'Izin', chip:'var(--blue-soft)'},
    Alpa:{icon:'❌', label:'Alpa', chip:'var(--red-soft)'},
  };

  function cardsHtml(){
    return (state.students||[]).map((s,i)=>{
      const st = avatarStyle(s.avatarIdx ?? i);
      const meta = STATUS_META[statuses[s.id]];
      return `
      <div class="absen-card" data-absen-id="${s.id}">
        <div class="avatar-wrap">
          <div class="avatar-ring" style="background:${st.bg}">${avatarOf(s)}</div>
          <div class="absen-badge">${meta.icon}</div>
        </div>
        <div class="student-name">${s.name.split(' ')[0]}</div>
        <div class="absen-status-label" style="background:${meta.chip}">${meta.label}</div>
      </div>`;
    }).join('');
  }

  openModal(isEdit ? 'Edit Absensi Hari Ini' : 'Absensi Hari Ini', `
    ${isEdit ? `<div class="jurnal-reminder"><span class="ic">📝</span><div><b>Mengedit absensi yang sudah tersimpan hari ini.</b><p>Perubahan otomatis menyesuaikan poin yang sudah diberikan.</p></div></div>` : ''}
    <div class="absen-hint">👆 Ketuk avatar untuk ganti status: Hadir → Sakit → Izin → Alpa</div>
    <div class="absen-grid" id="absGrid">${cardsHtml()}</div>
  `, `<button class="save-btn" id="absSave">${isEdit ? 'Update Absensi' : 'Simpan Absensi'}</button>`);

  function bindTaps(){
    document.querySelectorAll('[data-absen-id]').forEach(card=>{
      card.onclick = ()=>{
        const id = card.dataset.absenId;
        const idx = STATUS_ORDER.indexOf(statuses[id]);
        statuses[id] = STATUS_ORDER[(idx+1)%STATUS_ORDER.length];
        const meta = STATUS_META[statuses[id]];

        card.querySelector('.absen-badge').textContent = meta.icon;
        const label = card.querySelector('.absen-status-label');
        label.textContent = meta.label;
        label.style.background = meta.chip;

        const wrap = card.querySelector('.avatar-wrap');
        wrap.classList.remove('absen-bounce');
        void wrap.offsetWidth; // restart animation
        wrap.classList.add('absen-bounce');

        const fly = document.createElement('span');
        fly.className = 'absen-fly';
        fly.textContent = meta.icon;
        wrap.appendChild(fly);
        setTimeout(()=> fly.remove(), 800);
      };
    });
  }
  bindTaps();

  document.getElementById('absSave').onclick = ()=>{
    const deltas = Object.entries(statuses).map(([studentId,st])=>{
      const oldSt = savedToday[studentId];
      const oldPts = oldSt ? STATUS_PTS[oldSt] : 0;
      return {studentId, delta: STATUS_PTS[st] - oldPts};
    });
    const hadirCount = Object.values(statuses).filter(v=>v==='Hadir').length;
    state.absensi[today] = {...statuses};
    const {touched,totalPositive} = applyDeltas(deltas, isEdit ? 'Absensi (diperbarui)' : 'Absensi', 'absensi');
    closeModal();
    showCelebration(totalPositive, `Absensi tersimpan! ${hadirCount} siswa hadir hari ini.`, touched);
  };
}

/* --- JURNAL PEMBELAJARAN & CATATAN --- */
function latestJurnalBefore(dateKey){
  const list = (state.jurnal||[]).filter(j=>j.date < dateKey);
  if(list.length===0) return null;
  return list.sort((a,b)=> b.date.localeCompare(a.date))[0];
}

function openJurnalModal(){
  const today = todayKey();
  let existing = (state.jurnal||[]).find(j=>j.date===today);
  const prev = latestJurnalBefore(today);

  function draw(){
    const reminderHtml = (prev && prev.catatan) ? `
      <div class="jurnal-reminder">
        <span class="ic">📌</span>
        <div><b>Catatan pertemuan lalu (${fmtDateShort(prev.date)}):</b><p>${prev.catatan.replace(/&/g,'&amp;').replace(/</g,'&lt;')}</p></div>
      </div>` : '';
    openModal('Jurnal Pembelajaran', `
      ${reminderHtml}
      <div class="field-label">Tanggal</div>
      <input class="text-input" value="${fmtDateShort(today)}" disabled />
      <div class="field-label">Materi yang Diajarkan Hari Ini</div>
      <textarea class="text-input" id="jMateri" rows="3" placeholder="Contoh: Tajwid - hukum nun sukun & tanwin">${(existing?.materi||'').replace(/&/g,'&amp;').replace(/</g,'&lt;')}</textarea>
      <div class="field-label">Catatan untuk Pertemuan Berikutnya</div>
      <textarea class="text-input" id="jCatatan" rows="3" placeholder="Contoh: Lanjutkan latihan makhraj huruf, PR belum semua selesai">${(existing?.catatan||'').replace(/&/g,'&amp;').replace(/</g,'&lt;')}</textarea>
    `, `
      <div style="display:flex;gap:8px;">
        <button class="save-btn" style="flex:1;background:var(--sage-soft);color:var(--accent);" id="jHistoryBtn">📖 Riwayat</button>
        <button class="save-btn" style="flex:1;" id="jSave">Simpan Jurnal</button>
      </div>
    `);
    document.getElementById('jHistoryBtn').onclick = openJurnalHistoryModal;
    document.getElementById('jSave').onclick = ()=>{
      const materi = document.getElementById('jMateri').value.trim();
      const catatan = document.getElementById('jCatatan').value.trim();
      if(!materi && !catatan){ closeModal(); return; }
      state.jurnal = state.jurnal || [];
      if(existing){
        existing.materi = materi;
        existing.catatan = catatan;
      } else {
        existing = {id:uid(), date:today, materi, catatan, createdAt:Date.now()};
        state.jurnal.push(existing);
      }
      saveAndRender();
      closeModal();
      showToast('Jurnal pembelajaran tersimpan');
    };
  }
  draw();
}

function openJurnalHistoryModal(){
  function rows(){
    const list = [...(state.jurnal||[])].sort((a,b)=> b.date.localeCompare(a.date));
    if(list.length===0) return '<div class="empty-note">Belum ada jurnal tersimpan.</div>';
    return list.map(j=>`
      <div class="jurnal-card">
        <div class="jurnal-card-head">
          <b>${fmtDateShort(j.date)}</b>
          <button class="icon-btn danger" data-del-jurnal="${j.id}">🗑</button>
        </div>
        ${j.materi ? `<div class="jurnal-field"><span>📗 Materi:</span> ${j.materi.replace(/&/g,'&amp;').replace(/</g,'&lt;')}</div>` : ''}
        ${j.catatan ? `<div class="jurnal-field"><span>📌 Catatan:</span> ${j.catatan.replace(/&/g,'&amp;').replace(/</g,'&lt;')}</div>` : ''}
      </div>`).join('');
  }
  function draw(){
    openModal('Riwayat Jurnal', `<div id="jurnalHistRows">${rows()}</div>`, `<button class="save-btn" id="jHistClose">Tutup</button>`);
    document.querySelectorAll('[data-del-jurnal]').forEach(btn=>{
      btn.onclick = ()=>{
        state.jurnal = (state.jurnal||[]).filter(j=>j.id!==btn.dataset.delJurnal);
        saveAndRender();
        draw();
      };
    });
    document.getElementById('jHistClose').onclick = closeModal;
  }
  draw();
}

/* --- INPUT NILAI (Harian / Ujian digabung) --- */
function openNilaiModal(){
  let jenis = 'harian'; // harian | ujian
  const scores = {};

  function rowsHtml(){
    return studentRowsTemplate((s)=>`
      <input type="number" min="0" max="100" class="num-input" placeholder="—" data-score-for="${s.id}" value="${scores[s.id]??''}" />`);
  }

  function bodyHtml(){
    return `
      <div class="tab-toggle">
        <button class="${jenis==='harian'?'active':''}" data-njenis="harian">✏️ Nilai Harian</button>
        <button class="${jenis==='ujian'?'active':''}" data-njenis="ujian">📝 Ujian</button>
      </div>
      <div class="field-label">Mata Pelajaran</div>
      <input class="text-input" id="nSubject" list="mapelDatalist" placeholder="Contoh: Bahasa Arab" value="${(bodyHtml.mapel||'').replace(/"/g,'&quot;')}" />
      <datalist id="mapelDatalist">${(state.mataPelajaran||[]).map(m=>`<option value="${m.replace(/"/g,'&quot;')}">`).join('')}</datalist>
      ${jenis==='ujian' ? `
      <div class="field-label">Keterangan Ujian (opsional)</div>
      <input class="text-input" id="nKet" placeholder="Contoh: UTS Semester 1" value="${(bodyHtml.ket||'').replace(/"/g,'&quot;')}" />` : ''}
      <div class="field-label">Nilai per Siswa (0–100, kosongkan jika belum dinilai)</div>
      <div id="nRows">${rowsHtml()}</div>
    `;
  }
  bodyHtml.mapel = ''; bodyHtml.ket = '';

  function captureFields(){
    const subj = document.getElementById('nSubject');
    if(subj) bodyHtml.mapel = subj.value;
    const ket = document.getElementById('nKet');
    if(ket) bodyHtml.ket = ket.value;
    document.querySelectorAll('[data-score-for]').forEach(inp=>{ scores[inp.dataset.scoreFor] = inp.value; });
  }

  function draw(){
    openModal(jenis==='ujian' ? 'Input Nilai — Ujian' : 'Input Nilai — Harian', bodyHtml(), `<button class="save-btn" id="nSave">Simpan Nilai</button>`);
    document.querySelectorAll('[data-njenis]').forEach(btn=>{
      btn.onclick = ()=>{ captureFields(); jenis = btn.dataset.njenis; draw(); };
    });
    document.querySelectorAll('[data-score-for]').forEach(inp=>{
      inp.oninput = ()=>{ scores[inp.dataset.scoreFor] = inp.value; };
    });
    document.getElementById('nSave').onclick = ()=>{
      const subject = (document.getElementById('nSubject').value.trim()) || (jenis==='ujian' ? 'Ujian' : 'Nilai Harian');
      const ketEl = document.getElementById('nKet');
      const ket = ketEl ? ketEl.value.trim() : '';
      const deltas = [];
      const gradeEntries = [];
      document.querySelectorAll('[data-score-for]').forEach(inp=>{
        const v = inp.value.trim();
        if(v==='') return;
        const score = clamp(parseInt(v,10)||0,0,100);
        const pointDelta = jenis==='ujian' ? Math.round(score/5) : Math.round(score/10);
        deltas.push({studentId:inp.dataset.scoreFor, delta:pointDelta});
        gradeEntries.push({ id:uid(), studentId:inp.dataset.scoreFor, mapel:subject, jenis, keterangan:ket, nilai:score, date:todayKey(), ts:Date.now() });
      });
      if(deltas.length===0){ closeModal(); return; }
      state.grades = state.grades || [];
      gradeEntries.forEach(g=> state.grades.unshift(g));
      if(state.grades.length > 800) state.grades = state.grades.slice(0,800);
      const noteLabel = (jenis==='ujian' && ket) ? `${subject} — ${ket}` : subject;
      const {touched,totalPositive} = applyDeltas(deltas, noteLabel, jenis==='ujian'?'ujian':'nilai');
      closeModal();
      showCelebration(totalPositive, `Nilai "${noteLabel}" tersimpan untuk ${deltas.length} siswa.`, touched);
    };
  }
  draw();
}

/* --- NILAI RAPORT (olahan dari Nilai Harian + Ujian) --- */
function openRaportModal(){
  const mapelList = Array.from(new Set((state.grades||[]).map(g=>g.mapel))).sort((a,b)=>a.localeCompare(b));
  let mapel = mapelList[0] || '';

  function computeRows(){
    return (state.students||[]).map((s,i)=>{
      const g = (state.grades||[]).filter(x=>x.studentId===s.id && x.mapel===mapel);
      const harian = g.filter(x=>x.jenis==='harian').map(x=>x.nilai);
      const ujian = g.filter(x=>x.jenis==='ujian').map(x=>x.nilai);
      const avgH = harian.length ? Math.round(harian.reduce((a,b)=>a+b,0)/harian.length) : null;
      const avgU = ujian.length ? Math.round(ujian.reduce((a,b)=>a+b,0)/ujian.length) : null;
      let nilai = null;
      if(avgH!=null && avgU!=null) nilai = Math.round(avgH*0.4 + avgU*0.6);
      else if(avgH!=null) nilai = avgH;
      else if(avgU!=null) nilai = avgU;
      return {s, i, avgH, avgU, nilai};
    });
  }

  function bodyHtml(){
    if(mapelList.length===0){
      return `<div class="empty-note">Belum ada data nilai. Isi <b>Input Nilai</b> (Harian/Ujian) dulu, nanti otomatis muncul di sini.</div>`;
    }
    const rows = computeRows();
    const rowsHtml = rows.map(({s,i,avgH,avgU,nilai})=>{
      const st = avatarStyle(s.avatarIdx ?? i);
      return `<div class="raport-row">
        <div class="av-sm" style="background:${st.bg}">${avatarOf(s)}</div>
        <div class="fname" style="flex:1;">${s.name.split(' ')[0]}</div>
        <div class="raport-mini">${avgH ?? '—'}</div>
        <div class="raport-mini">${avgU ?? '—'}</div>
        <div class="raport-final">${nilai ?? '—'}</div>
      </div>`;
    }).join('');
    return `
      <div class="field-label">Pilih Mata Pelajaran</div>
      <select class="text-input" id="rMapel">${mapelList.map(m=>`<option value="${m.replace(/"/g,'&quot;')}" ${m===mapel?'selected':''}>${m}</option>`).join('')}</select>
      <div class="field-label">Rekap Nilai <span class="sub">Rapor = 40% Harian + 60% Ujian</span></div>
      <div class="raport-row raport-head">
        <div style="width:34px;"></div>
        <div style="flex:1;font-size:10.5px;font-weight:800;color:var(--ink-soft);">Siswa</div>
        <div class="raport-mini head">Harian</div>
        <div class="raport-mini head">Ujian</div>
        <div class="raport-final head">Rapor</div>
      </div>
      <div id="rRows">${rowsHtml}</div>
    `;
  }

  function draw(){
    openModal('Nilai Raport', bodyHtml(), mapelList.length ? `<button class="save-btn" id="rSave">Simpan sebagai Nilai Raport</button>` : '');
    const sel = document.getElementById('rMapel');
    if(sel) sel.onchange = ()=>{ mapel = sel.value; draw(); };
    const saveBtn = document.getElementById('rSave');
    if(saveBtn) saveBtn.onclick = ()=>{
      const rows = computeRows().filter(r=>r.nilai!=null);
      if(rows.length===0){ showToast('Belum ada nilai yang bisa diolah untuk mapel ini'); return; }
      state.raport = (state.raport||[]).filter(r=>r.mapel!==mapel);
      rows.forEach(({s,avgH,avgU,nilai})=>{
        state.raport.push({ id:uid(), studentId:s.id, mapel, avgHarian:avgH, avgUjian:avgU, nilai, ts:Date.now() });
      });
      saveAndRender();
      closeModal();
      showToast(`Nilai Raport "${mapel}" tersimpan untuk ${rows.length} siswa.`);
    };
  }
  draw();
}

/* --- PIKET --- */
function openPiketModal(){
  let selectedDay = dayName()==='Minggu' ? 'Senin' : dayName();
  if(!DAYS.includes(selectedDay)) selectedDay = 'Senin';
  const doneToday = new Set();

  function assignedIds(){ return state.piket[selectedDay] || []; }

  function bodyHtml(){
    const dayTabs = DAYS.map(d=>`<button class="day-tab ${d===selectedDay?'active':''}" data-day="${d}">${d}</button>`).join('');
    const assigned = assignedIds();
    const rows = (state.students||[]).map((s,i)=>{
      const st = avatarStyle(s.avatarIdx ?? i);
      const isAssigned = assigned.includes(s.id);
      return `<div class="form-row">
        <div class="av-sm" style="background:${st.bg}">${avatarOf(s)}</div>
        <div class="fname">${s.name.split(' ')[0]}</div>
        <button class="chk-box ${isAssigned?'on':''}" data-assign-toggle="${s.id}">${isAssigned?'✓':''}</button>
      </div>`;
    }).join('');
    return `
      <div class="day-tabs">${dayTabs}</div>
      <div class="field-label">Petugas Piket Hari ${selectedDay}</div>
      <div id="piketRows">${rows}</div>
      <div class="mini-note" style="margin-top:8px;">Centang siswa yang bertugas piket pada hari ini. Simpan jadwal untuk minggu depan, atau tandai selesai jika piket hari ini sudah dikerjakan.</div>
    `;
  }

  function footHtml(){
    return `
      <div style="display:flex;gap:8px;">
        <button class="save-btn" style="flex:1;background:var(--sage-soft);color:var(--accent);" id="piketSaveSchedule">Simpan Jadwal</button>
        ${selectedDay===dayName() ? `<button class="save-btn" style="flex:1;" id="piketMarkDone">Tandai Selesai +5</button>` : ''}
      </div>`;
  }

  function draw(){
    openModal('Jadwal Piket', bodyHtml(), footHtml());
    document.querySelectorAll('[data-day]').forEach(btn=>{
      btn.onclick = ()=>{ selectedDay = btn.dataset.day; draw(); };
    });
    document.querySelectorAll('[data-assign-toggle]').forEach(btn=>{
      btn.onclick = ()=>{
        const id = btn.dataset.assignToggle;
        const arr = state.piket[selectedDay] || [];
        state.piket[selectedDay] = arr.includes(id) ? arr.filter(x=>x!==id) : [...arr, id];
        draw();
      };
    });
    const saveBtn = document.getElementById('piketSaveSchedule');
    if(saveBtn) saveBtn.onclick = ()=>{ saveAndRender(); closeModal(); showToast('Jadwal piket disimpan'); };
    const doneBtn = document.getElementById('piketMarkDone');
    if(doneBtn) doneBtn.onclick = ()=>{
      const ids = assignedIds();
      if(ids.length===0){ showToast('Belum ada siswa yang bertugas hari ini'); return; }
      const deltas = ids.map(id=>({studentId:id, delta:5}));
      const {touched,totalPositive} = applyDeltas(deltas, 'Piket selesai', 'piket');
      closeModal();
      showCelebration(totalPositive, `Piket hari ${selectedDay} selesai dikerjakan!`, touched);
    };
  }
  draw();
}

